'use strict';
let intelligence=null,sourceBusy=false,evidencePage=1,loadSequence=0,filterTimer;const documentViews=new Map();
function renderIntelligence(){if(!intelligence)return;const classes={official_announcement:'OFFICIAL ANNOUNCEMENT',official_record:'OFFICIAL RECORD',company_statement:'COMPANY STATEMENT',independent_reporting:'INDEPENDENT REPORTING',social_lead:'SOCIAL LEAD'};
 $('samAccessStatus').textContent=intelligence.samConfigured?'Configured in server memory':'Not configured';
 $('sourceStatus').textContent=`${intelligence.sources.filter(s=>s.health.state==='healthy').length} healthy sources / ${intelligence.totalEvidence||intelligence.evidence.length} stored headlines / ${intelligence.running?'scan running':intelligence.lastScan?'last scan '+new Date(intelligence.lastScan).toLocaleString():'not yet scanned'}`;
 $('sourceHealth').innerHTML=intelligence.sources.map(s=>`<article class="source"><div><b>${esc(s.name)}</b><p>${esc(classes[s.class]||s.class)} · ${esc((s.health.state||s.health.status).replaceAll('_',' ').toUpperCase())}</p><p class="muted">${esc((s.health.state==='failing'?s.health.error:null)||s.health.reason||(s.health.checkedAt?'Checked '+new Date(s.health.checkedAt).toLocaleString():'Awaiting first collection'))}</p><p class="muted">Last successful check: ${esc(s.health.last_successful_fetch_at||'NEVER')}<br>Last attempted: ${esc(s.health.last_attempted_check_at||'NEVER')}<br>Next attempt: ${esc(s.health.next_scheduled_attempt_at||'UNKNOWN')}<br>Consecutive failures: ${esc(s.health.consecutive_failures)}<br>Coverage: ${esc(s.health.historical_coverage)}</p>${s.health.quota?`<p>Local quota: ${esc(s.health.quota.used)} / ${esc(s.health.quota.dailyLimit)} used · Next eligible: ${esc(s.health.quota.nextEligibleAt)}</p>`:''}${s.health.coverage?`<p class="muted">${esc(s.health.coverage.postedFrom)} → ${esc(s.health.coverage.postedTo)} / ${s.health.coverage.returned} of ${s.health.coverage.total} notices / ${s.health.coverage.complete?'window pages collected':'PARTIAL / mutable pagination'}</p>`:''}</div><a href="${esc(s.url)}" target="_blank" rel="noopener">SOURCE</a></article>`).join('');
 if($('eventTypeFilter').options.length===1)(intelligence.eventTypes||[]).forEach(type=>{const option=document.createElement('option');option.value=type;option.textContent=type.replaceAll('_',' ');$('eventTypeFilter').append(option)});
 const eventFilter=$('eventTypeFilter').value;
 const query=$('evidenceQuery').value.trim().toLowerCase(),type=$('evidenceType').value,cuesOnly=$('cuesOnly').checked;
 const evidence=intelligence.evidence.filter(r=>(!query||[r.title,...r.companyMentions,...r.cues].join(' ').toLowerCase().includes(query))&&(!type||r.sourceClass===type)&&(!eventFilter||r.event?.eventType===eventFilter)&&(!cuesOnly||r.cues.length||r.companyMentions.length));
 $('evidenceCount').textContent=`${intelligence.pagination?.total??evidence.length} matches / page ${intelligence.pagination?.page||1} of ${intelligence.pagination?.pages||1}`;
 $('evidenceFeed').innerHTML=evidence.length?evidence.slice(0,100).map(r=>`<article class="evidence"><span class="eyebrow">${esc(classes[r.sourceClass]||r.sourceClass)} / RESEARCH LEAD</span><h3><a href="${esc(r.url)}" target="_blank" rel="noopener">${esc(r.title)}</a></h3><p>${esc(r.sourceName)} · ${esc(r.companyMentions.join(', ')||'Company identity not resolved')}</p>${r.noticeId?`<p>Notice: ${esc(r.noticeType)} · Agency: ${esc(r.agency)} · Solicitation: ${esc(r.solicitationNumber)} · NAICS: ${esc(r.naics)}</p><p>Reported awardee: ${esc(r.award?.recipientName)} · UEI: ${esc(r.award?.recipientUei)} · Notice award amount: ${esc(r.award?.amount==null?'UNKNOWN':Number(r.award.amount).toLocaleString('en-US')+' / currency not supplied')}</p>`:''}<p class="muted">Cues: ${esc(r.cues.join(', ')||'none')} · First seen: ${esc(new Date(r.firstSeen).toLocaleString())}</p><p class="muted">Published: ${esc(r.publishedAt||'Not reported')} · Collected: ${esc(r.collectionScope)}. Full claim not verified.</p>${eventDetails(r)}<button data-document="${esc(r.id)}">RETRIEVE / REVIEW DOCUMENT</button><div id="doc-${esc(r.id)}"></div></article>`).join(''):'No evidence matches. Check source health or broaden the filters.';
 documentViews.forEach((html,id)=>{const node=$('doc-'+id);if(node){node.innerHTML=html;bindSavedDocumentWatch(node,id)}});
 $('evidenceFeed').querySelectorAll('[data-document]').forEach(b=>b.onclick=()=>reviewDocument(b.dataset.document,b));
 $('evidencePrevious').disabled=evidencePage<=1;$('evidenceNext').disabled=evidencePage>=(intelligence.pagination?.pages||1);$('scanSources').disabled=Boolean(intelligence.readOnly)||sourceBusy;$('samKeyForm').querySelectorAll('input,button').forEach(b=>b.disabled=Boolean(intelligence.readOnly));if(intelligence.readOnly)$('samAccessStatus').textContent=intelligence.samConfigured?'Configured in active collector':'Active collector has no SAM key';
 renderPersistentIntelligence();
 $('seedCompanies').textContent=intelligence.watchlist.map(c=>c.name).join(' · ');
}
async function loadIntelligence(){const sequence=++loadSequence;try{const params=new URLSearchParams({page:String(evidencePage),q:$('evidenceQuery').value,class:$('evidenceType').value,eventType:$('eventTypeFilter').value,cuesOnly:$('cuesOnly').checked?'1':'0'});const response=await fetch('/api/intelligence?'+params);if(!response.ok)throw new Error('Local collector unavailable');const result=await response.json();if(sequence!==loadSequence)return;intelligence=result;renderIntelligence()}catch(e){$('sourceStatus').textContent='Source collection requires the local Contract Sentinel server. Award search can still work independently.'}}
$('scanSources').onclick=async()=>{if(sourceBusy)return;sourceBusy=true;$('scanSources').disabled=true;$('sourceStatus').textContent='Collecting configured public sources…';try{const response=await fetch('/api/intelligence/scan',{method:'POST',headers:{'X-Sentinel-Action':'scan'}});if(!response.ok)throw new Error(response.status===409?'A source scan is already running.':'Unable to start source scan.');await loadIntelligence()}catch(e){$('sourceStatus').textContent=e.message}finally{sourceBusy=false;$('scanSources').disabled=false}};
['evidenceQuery','evidenceType','eventTypeFilter','cuesOnly'].forEach(id=>$(id).addEventListener('input',()=>{evidencePage=1;clearTimeout(filterTimer);filterTimer=setTimeout(loadIntelligence,250)}));
document.querySelector('[data-view="sources"]').addEventListener('click',loadIntelligence);
loadIntelligence();setInterval(()=>{if(!$('sources').hidden)loadIntelligence()},60000);

function renderPersistentIntelligence(){
 const profiles=intelligence.issuers||[]; $('issuerProfiles').innerHTML=profiles.length?profiles.map(p=>`<article class="source"><div><b>${esc(p.researchName)} / ${esc(p.ticker||'UNRESOLVED')}</b><p>${esc(p.legalName||p.status)} · CIK ${esc(p.cik||'—')}</p><p class="muted">${esc(p.relationshipScope)} · ${esc(p.checkedAt||'')}</p></div>${p.cik?`<a href="https://www.sec.gov/edgar/browse/?CIK=${encodeURIComponent(p.cik)}" target="_blank" rel="noopener">SEC</a>`:''}</article>`).join(''):'Issuer directory has not been collected yet.';
 if($('persistentCompany').options.length===1)intelligence.watchlist.forEach(c=>{const option=document.createElement('option');option.value=c.name;option.textContent=c.name;$('persistentCompany').append(option)});
 const a=intelligence.alerts||{rules:[],events:[],unread:0};if(typeof syncAwardRules==='function')syncAwardRules(a.rules);$('persistentCount').textContent=`${a.unread} unread / ${a.events.length} saved alerts`;
 $('persistentRules').innerHTML=a.rules.length?a.rules.map(r=>`<article class="source"><b>${esc(r.kind==='loaded_award'?r.term:r.target||r.company||'All headlines')} / ${esc(r.kind==='loaded_award'?'LOADED AWARD ≥ USD '+r.minimum:r.kind==='document_change'?'SAVED DOCUMENT CHANGES':r.kind==='funding_change'?'SAVED FUNDING CHANGES':r.cue)}</b><button data-remove-rule="${esc(r.id)}">REMOVE RULE</button></article>`).join(''):'No server rules saved.';
 const filteredAlerts=a.events.filter(e=>(!$('alertKindFilter').value||e.kind===$('alertKindFilter').value)&&(!$('alertUnreadOnly').checked||!e.readAt));$('alertVisibleCount').textContent=`Showing ${Math.min(filteredAlerts.length,50)} of ${filteredAlerts.length} matching saved alerts / newest first`;
 $('persistentEvents').innerHTML=filteredAlerts.slice(0,50).map(e=>`<article class="evidence"><span class="eyebrow">${e.readAt?'READ':'UNREAD'} / ${esc(e.kind||'LEGACY MATCH')} / RESEARCH LEAD / ${esc(e.cue)}</span><h3><a href="${esc(e.url)}" target="_blank" rel="noopener">${esc(e.title)}</a></h3><p>${esc(e.sourceName)} · ${esc(e.company||'Any company')} · Detected ${esc(new Date(e.createdAt).toLocaleString())}</p>${e.changes?.length?`<p>${esc(e.ruleExplanation)}</p><dl>${e.changes.map(c=>`<dt>${esc(c.field.replaceAll('_',' '))}</dt><dd>Previous: ${esc(JSON.stringify(c.previous))}<br>Current: ${esc(JSON.stringify(c.current))}</dd>`).join('')}</dl><p>Source changes require review; financial materiality has not been assessed.</p>`:''}${e.eventSnapshot?eventDetails({event:e.eventSnapshot,title:e.title}):e.awardSnapshot?`<p>Saved loaded-page record: ${esc(e.awardSnapshot.id)} / reported amount ${esc(e.awardSnapshot.amount??'UNKNOWN')} USD / ${e.awardSnapshot.sub?'SUBAWARD':'PRIME'}. Browser-submitted record requires source verification; this is not a background award search.</p>`:['funding_change','document_change'].includes(e.kind)?`<p>Previous retrieval ${esc(e.previousRetrievedAt)} / current retrieval ${esc(e.currentRetrievedAt)}. Showing ${esc(e.changes.length)} of ${esc(e.changeCount)} field changes. Hashes: ${esc(e.previousContentHash)} → ${esc(e.contentHash)}.</p>`:'<p class="muted">Older alert: no detection-time structured snapshot captured.</p>'}${e.readAt?'':`<button data-read-alert="${esc(e.id)}">MARK READ</button>`}</article>`).join('');
 $('persistentRules').querySelectorAll('[data-remove-rule]').forEach(b=>b.onclick=()=>persistentAction('/rules/remove',{id:b.dataset.removeRule}));$('persistentEvents').querySelectorAll('[data-read-alert]').forEach(b=>b.onclick=()=>persistentAction('/alerts/read',{id:b.dataset.readAlert}));
}
async function persistentAction(route,input){try{const response=await fetch('/api/intelligence'+route,{method:'POST',headers:{'Content-Type':'application/json','X-Sentinel-Action':'scan'},body:JSON.stringify(input)});const result=await response.json();if(!response.ok)throw new Error(result.error||'Action failed');await loadIntelligence();$('persistentStatus').textContent='Saved in the local server store.';}catch(e){$('persistentStatus').textContent=e.message}}
$('persistentRuleForm').onsubmit=e=>{e.preventDefault();persistentAction('/rules',{company:$('persistentCompany').value,cue:$('persistentCue').value})};

async function configureSam(key){try{const response=await fetch('/api/intelligence/sam-key',{method:'POST',headers:{'Content-Type':'application/json','X-Sentinel-Action':'scan'},body:JSON.stringify({key})});$('samKey').value='';if(!response.ok)throw new Error('SAM key could not be configured');await loadIntelligence();$('samAccessStatus').textContent=key?'Configured in server memory; scan to verify':'Key cleared';}catch(e){$('samKey').value='';$('samAccessStatus').textContent=e.message;}}
$('samKeyForm').onsubmit=e=>{e.preventDefault();const key=$('samKey').value.trim();if(key)configureSam(key)};$('forgetSamKey').onclick=()=>configureSam('');

function eventDetails(row){const e=row?.event;if(!e)return '';const value=v=>v==null?'UNKNOWN':typeof v==='object'?JSON.stringify(v):String(v);const time=t=>t?.value?value(t.value)+' / '+t.precision+(t.timezone?' / '+t.timezone:''):'UNKNOWN';const amount=f=>f?.value==null?'UNKNOWN':Number(f.value).toLocaleString('en-US')+' / '+(f.currency||'currency UNKNOWN');const fields=[['Headline',row.title],['Company',null],['Ticker',e.identity.ticker],['Legal recipient (source reported)',e.identity.legalRecipient],['Government buyer',e.governmentBuyer],['Program',e.program],['Event type (provisional)',e.eventType],['Contract / solicitation ID',[e.contractId,e.solicitationId].filter(Boolean).join(' / ')||null],['Newly obligated amount',e.financial.newlyObligatedAmount],['Headline announced amount',amount(e.financial.headlineAmount)],['Base value',e.financial.baseValue],['Ceiling',e.financial.maximumPotentialValue],['Options',e.financial.unexercisedOptions],['Company allocation',e.financial.companyAllocation],['Duration',e.financial.duration],['New business or renewal',e.financial.newWorkOrRenewal],['Materiality assessment',e.dimensions.financialMateriality],['Source confidence',e.dimensions.sourceConfidence],['Event certainty',e.dimensions.eventCertainty],['Novelty',e.dimensions.novelty],['Event / award date',time(e.timestamps.eventDate)],['Source publication',time(e.timestamps.sourcePublication)],['Earliest known publication',time(e.timestamps.earliestKnownMatchingPublication)],['First detected',time(e.timestamps.firstDetected)],['Last evidence change',time(e.timestamps.lastUpdated)],['Prior related announcement',null],['Price change since publication',null],['Price change since detection',null],['Why this may matter',e.whyThisMayMatter],['Classification basis',e.basis],['Review scope',e.reviewScope],['Uncertainty flags',e.flags.join(', ')||'None detected by headline rules; not a complete review'],['What remains unknown',e.unknowns.join('; ')],['Priority',e.priority+' / '+e.priorityReason]];return `<details class="event-details"><summary>${esc(e.eventType.replaceAll('_',' '))} / ${esc(e.priority)} RESEARCH / VIEW STRUCTURED RECORD</summary><p>Provisional classification. Underlying documents have not been reviewed; keyword matches do not confirm an event or its economics.</p><dl>${fields.map(([label,v])=>`<dt>${esc(label)}</dt><dd>${esc(value(v))}</dd>`).join('')}</dl>${e.primarySourceUrl?`<a href="${esc(e.primarySourceUrl)}" target="_blank" rel="noopener">PRIMARY SOURCE</a>`:''}<p>Supporting sources: UNKNOWN / no independent corroboration linked.</p></details>`;}

async function reviewDocument(id,button){const target=$('doc-'+id);button.disabled=true;target.textContent='Retrieving supported HTML source…';try{let response=await fetch('/api/documents',{method:'POST',headers:{'Content-Type':'application/json','X-Sentinel-Action':'scan'},body:JSON.stringify({id})});let record=await response.json();let retained=false;if(!response.ok){const cached=await fetch('/api/documents?id='+encodeURIComponent(id));const saved=await cached.json();if(!cached.ok||!saved?.versions?.length)throw new Error(record.error||'Document retrieval failed');record=saved;retained=true;}const v=record.versions.at(-1);target.innerHTML='<button data-follow-document="'+esc(id)+'">FOLLOW SAVED DOCUMENT CHANGES</button><p data-follow-status></p>'+(retained?'<p>Latest retrieval failed. Showing the last saved snapshot; this is not a fresh source check.</p>':'')+'<details open class="event-details"><summary>'+esc(record.versions.length+' saved versions / '+v.change.kind.replaceAll('_',' '))+'</summary><p>EXTRACTED TEXT / ANALYST VERIFICATION PENDING. Amount mentions do not establish obligations or supplier allocations.</p><p>Retrieved '+esc(v.retrievedAt)+' · Published '+esc(v.publishedAt||'UNKNOWN')+'</p><p>Version '+esc(v.hash)+'</p><p>Passage event candidates: '+esc((v.candidateEvents||[]).map(c=>c.passageId+': '+c.interpretation.eventType).join(' / ')||'No supported phrases')+'</p>'+v.passages.filter(p=>p.researchCue).slice(0,30).map(p=>'<p><b>'+esc(p.id)+'</b> '+esc(p.text)+'</p>').join('')+(v.change.kind==='text_changed'?'<p>Added passage IDs: '+esc(v.change.added.join(', ')||'none')+'</p><h4>REMOVED / PREVIOUS TEXT</h4>'+v.change.removed.map(p=>'<p>'+esc(p.id)+': '+esc(p.text)+'</p>').join(''):'')+'</details>';target.querySelector('[data-follow-document]').onclick=async()=>{try{await companyAction('/api/intelligence/rules',{kind:'document_change',target:id});target.querySelector('[data-follow-status]').textContent='Following saved versions; approved HTML refreshes daily while the collector runs.';}catch(e){target.querySelector('[data-follow-status]').textContent=e.message}};documentViews.set(id,target.innerHTML);}catch(e){target.textContent=e.message;}finally{button.disabled=false;}}

$('evidencePrevious').onclick=()=>{if(evidencePage>1){evidencePage--;loadIntelligence()}};$('evidenceNext').onclick=()=>{evidencePage++;loadIntelligence()};
let eventPage=1,eventSequence=0,eventTimer;
async function loadEventTimeline(){const sequence=++eventSequence;try{const params=new URLSearchParams({page:String(eventPage),q:$('eventQuery').value,stage:$('eventStage').value});const response=await fetch('/api/events?'+params);if(!response.ok)throw new Error('Event timeline unavailable');const data=await response.json();if(sequence!==eventSequence)return;$('eventTimelineStatus').textContent=`${data.pagination.total} observed source events / page ${data.pagination.page} of ${data.pagination.pages}`;$('eventPrevious').disabled=eventPage<=1;$('eventNext').disabled=eventPage>=data.pagination.pages;$('eventTimeline').innerHTML=data.events.length?data.events.map(e=>`<details class="event-details"><summary>${esc(e.procurementStage.toUpperCase())} / ${esc(e.linkedDocuments[0].title)}</summary><p>PROVISIONAL / PUBLIC PARENT UNRESOLVED</p><p>Source publication: ${esc(e.sourcePublishedAt||'UNKNOWN')} (${esc(e.sourcePublicationPrecision)}) · First observed: ${esc(e.firstObservedAt)}</p><p>Contractor: ${esc(e.contractor||'UNKNOWN')} · Agency: ${esc(e.agency||'UNKNOWN')} · Contract: ${esc(e.contractId||'UNKNOWN')}</p><p>Announced amount: ${esc(e.financial.headlineAmount?.value??'UNKNOWN')} · Newly obligated: ${esc(e.financial.newlyObligatedAmount??'UNKNOWN')} · Allocation: ${esc(e.financial.companyAllocation??'UNKNOWN')}</p><p>Research mentions: ${esc(e.researchCompanyMentions.join(', ')||'Unresolved')} · Corrections: ${e.correctionHistory.length}</p>${e.linkedDocuments.map(d=>`<a href="${esc(d.url)}" target="_blank" rel="noopener">${esc(d.sourceClass)} / PRIMARY EVIDENCE</a>`).join('')}<p>Event ${esc(e.id)} / extraction version ${e.extractionVersion}</p>${e.correctionHistory.map(c=>`<p>${esc(c.changedAt)}: ${esc(c.previous.eventType)} revised (${esc(c.reason)}).</p>`).join('')}</details>`).join(''):'No observed events match. Incomplete coverage means this does not establish absence of activity.';}catch(e){$('eventTimelineStatus').textContent=e.message;}}
['eventQuery','eventStage'].forEach(id=>$(id).addEventListener('input',()=>{eventPage=1;clearTimeout(eventTimer);eventTimer=setTimeout(loadEventTimeline,250)}));$('eventPrevious').onclick=()=>{eventPage--;loadEventTimeline()};$('eventNext').onclick=()=>{eventPage++;loadEventTimeline()};document.querySelector('[data-view="sources"]').addEventListener('click',loadEventTimeline);loadEventTimeline();
async function loadEntityRelationships(){try{const response=await fetch('/api/entities');if(!response.ok)throw new Error();const ledger=await response.json();$('entityRelationships').innerHTML=ledger.relationships.map(r=>{const child=ledger.entities.find(e=>e.id===r.childId),parent=ledger.entities.find(e=>e.id===r.parentId);return `<details class="event-details"><summary>${esc(child.legalName)} → ${esc(parent.legalName)} / EVIDENCE AS OF ${esc(r.evidenceAsOf)}</summary><p>Relationship starts: ${esc(r.effectiveFrom||'UNKNOWN')} · End date: ${esc(r.effectiveUntil||'UNKNOWN')} · Reviewed: ${esc(ledger.reviewedAt)}</p><p>Public listing evidence: ${esc(parent.publicListing?.ticker||'UNKNOWN')} (${esc(parent.publicListing?.exchange||'UNKNOWN')}) as of ${esc(parent.publicListing?.evidenceAsOf||'UNKNOWN')}. No automatic award-recipient ticker assignment.</p>${r.sources.map(source=>`<p><a href="${esc(source.url)}" target="_blank" rel="noopener">${esc(source.section)}</a><br>${esc(source.supportingPassage)}<br>${esc(source.scope)}</p>`).join('')}<p>Unresolved: ${esc(r.limitations.join('; '))}</p></details>`;}).join('');}catch{$('entityRelationships').textContent='Corporate evidence unavailable; no recipient ownership inferred.'}}
loadEntityRelationships();

document.querySelector('[data-view="alerts"]').addEventListener('click',loadIntelligence);
setInterval(()=>{if(!$('alerts').hidden)loadIntelligence()},60000);

['alertKindFilter','alertUnreadOnly'].forEach(id=>$(id).onchange=renderPersistentIntelligence);

function bindSavedDocumentWatch(target,id){const button=target.querySelector('[data-follow-document]');if(button)button.onclick=async()=>{try{await companyAction('/api/intelligence/rules',{kind:'document_change',target:id});target.querySelector('[data-follow-status]').textContent='Following saved versions. Retrieve again to check the source.';}catch(e){target.querySelector('[data-follow-status]').textContent=e.message}}}

async function loadRefreshStatus(){try{const r=await fetch('/api/refresh-jobs');if(!r.ok)throw new Error();const s=await r.json();$('scheduledRefreshStatus').innerHTML='<details><summary>SCHEDULED SAVED-RECORD REFRESHES</summary><p>'+esc(s.coverage)+'</p><p>UTC daily jobs: '+esc(s.used)+' / '+esc(s.dailyBudget)+'</p>'+Object.values(s.jobs).map(j=>'<p>'+esc(j.kind)+' / '+esc(j.target)+' / '+(j.enabled?'FOLLOWED':'DISABLED')+'<br>Success '+esc(j.lastSuccessAt||'NEVER')+' / next '+esc(j.nextAttemptAt||'DUE')+'<br>'+esc(j.error||'')+'</p>').join('')+'</details>';}catch{$('scheduledRefreshStatus').textContent='Refresh status unavailable';}}document.querySelector('[data-view="alerts"]').addEventListener('click',loadRefreshStatus);loadRefreshStatus();setInterval(()=>{if(!$('alerts').hidden)loadRefreshStatus()},60000);
